```
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <nlohmann/json.hpp>
using json = nlohmann::json;
// Define a restaurant class to store restaurant attributes
class Restaurant {
public:
    std::string name;
    std::string location;
    std::string cuisine;
    std::string uniqueDish;
    double price;
    double rating;
    std::vector<std::string> reviews;
};
// Parse JSON data and store in vector of restaurant objects
std::vector<Restaurant> parseJSON(json data) {
    std::vector<Restaurant> restaurants;
    for (auto& r : data["restaurants"]) {
        Restaurant restaurant;
        restaurant.name = r["name"];
        restaurant.location = r["location"];
        restaurant.cuisine = r["cuisine"];
        restaurant.uniqueDish = r["uniqueDish"];
        // Add more attributes such as price, rating, and reviews
        restaurants.push_back(restaurant);
    }
    return restaurants;
}
// Recommend unique dishes based on cuisine type
std::vector<std::string> recommendByCuisine(std::vector<Restaurant> restaurants, std::string cuisine) {
    std::vector<std::string> dishes;
    for (auto& r : restaurants) {
        if (r.cuisine == cuisine) {
            dishes.push_back(r.uniqueDish);
        }
    }
    return dishes;
}
// Recommend unique dishes based on price range
std::vector<std::string> recommendByPrice(std::vector<Restaurant> restaurants, double minPrice, double maxPrice) {
    std::vector<std::string> dishes;
    for (auto& r : restaurants) {
        if (r.price >= minPrice && r.price <= maxPrice) {
            dishes.push_back(r.uniqueDish);
        }
    }
    return dishes;
}
// Recommend unique dishes based on restaurant ratings
std::vector<std::string> recommendByRating(std::vector<Restaurant> restaurants, double minRating) {
    std::vector<std::string> dishes;
    for (auto& r : restaurants) {
        if (r.rating >= minRating) {
            dishes.push_back(r.uniqueDish);
        }
    }
    return dishes;
}
// Recommend unique dishes based on customer reviews
std::vector<std::string> recommendByReviews(std::vector<Restaurant> restaurants, std::string keyword) {
    std::vector<std::string> dishes;
    for (auto& r : restaurants) {
        for (auto& review : r.reviews) {
            if (review.find(keyword) != std::string::npos) {
                dishes.push_back(r.uniqueDish);
                break;
            }
        }
    }
    return dishes;
}
// Main function
int main() {
    // Parse JSON data
    json data = R"({
        "restaurants": [
            {
                "name": "The Secret Garden",
                "location": "123 Main St.",
                "cuisine": "vegetarian",
                "uniqueDish": "veggie burger",
                "price": 10.99,
                "rating": 4.5,
                "reviews": ["Great food!", "Friendly service."]
            },
            {
                "name": "Taste of Italy",
                "location": "456 Oak St.",
                "cuisine": "Italian",
                "uniqueDish": "gnocchi alla sorrentina",
                "price": 15.99,
                "rating": 4.0,
                "reviews": ["Authentic Italian cuisine.", "Cozy atmosphere."]
            },
            {
                "name": "Soul Food Kitchen",
                "location": "789 Maple Ave.",
                "cuisine": "southern",
                "uniqueDish": "fried catfish",
                "price": 12.99,
                "rating": 3.5,
                "reviews": ["Delicious comfort food.", "Generous portions."]
            },
            {
                "name": "Spice of Life",
                "location": "1010 Elm St.",
                "cuisine": "Indian",
                "uniqueDish": "saag paneer",
                "price": 14.99,
                "rating": 4.2,
                "reviews": ["Best Indian food in town!", "Attentive staff."]
            }
        ]
    })"_json;
    // Parse JSON data and store in vector of restaurant objects
    std::vector<Restaurant> restaurants = parseJSON(data);
    // Test recommendation functions
    std::vector<std::string> cuisineDishes = recommendByCuisine(restaurants, "Indian");
    std::vector<std::string> priceDishes = recommendByPrice(restaurants, 10.0, 15.0);
    std::vector<std::string> ratingDishes = recommendByRating(restaurants, 4.0);
    std::vector<std::string> reviewDishes = recommendByReviews(restaurants, "friendly");
    // Print recommended dishes
    std::cout << "Recommended dishes based on cuisine type: ";
    for (auto& d : cuisineDishes) {
        std::cout << d << ", ";
    }
    std::cout << std::endl;
    std::cout << "Recommended dishes based on price range: ";
    for (auto& d : priceDishes) {
        std::cout << d << ", ";
    }
    std::cout << std::endl;
    std::cout << "Recommended dishes based on restaurant ratings: ";
    for (auto& d : ratingDishes) {
        std::cout << d << ", ";
    }
    std::cout << std::endl;
    std::cout << "Recommended dishes based on customer reviews: ";
    for (auto& d : reviewDishes) {
        std::cout << d << ", ";
    }
    std::cout << std::endl;
    return 0;
}
```
