How can we implement safety features in a Swift app designed for construction workers? The app will include information on proper tool usage and safety guidelines, as well as training resources and reminders for safety gear usage. It will also feature a tool inspection and maintenance tracker to ensure that all equipment is up-to-date and safe for use. 
Here is an example of Swift code for the inspection tracker: 
struct Tool {
    var name: String
    var lastInspected: Date
    var inspectionFrequency: Int //in days

    func isDueForInspection() -> Bool {
        let nextInspection = Calendar.current.date(byAdding: .day, value: inspectionFrequency, to: lastInspected)!
        let currentDate = Date()
        return nextInspection <= currentDate
    }
}
class ToolTracker {
    var tools: [Tool] = []

    func addTool(name: String, lastInspected: Date, inspectionFrequency: Int) {
        let newTool = Tool(name: name, lastInspected: lastInspected, inspectionFrequency: inspectionFrequency)
        tools.append(newTool)
    }

    func getToolsDueForInspection() -> [Tool] {
        var dueTools: [Tool] = []
        for tool in tools {
            if tool.isDueForInspection() {
                dueTools.append(tool)
            }
        }
        return dueTools
    }
}
let tracker = ToolTracker()
