    public static List<TaskGroup> groupAndFilterTasks(Map<String, Task> tasks, LocalDate startDate, LocalDate endDate, int threshold) {
        List<Task> filteredTasks = tasks.values().stream()
                .filter(task -> task.getPriority() > threshold && task.getDeadline().isAfter(startDate.minusDays(1)) && task.getDeadline().isBefore(endDate.plusDays(1)))
                .sorted((t1, t2) -> t2.getPriority() - t1.getPriority())
                .collect(Collectors.toList());

        Map<LocalDate, List<Task>> taskGroupsByDeadline = new HashMap<>();
        for (Task task : filteredTasks) {
            LocalDate deadline = task.getDeadline();
            if (!taskGroupsByDeadline.containsKey(deadline)) {
                taskGroupsByDeadline.put(deadline, new ArrayList<>());
            }
            taskGroupsByDeadline.get(deadline).add(task);
        }

        List<TaskGroup> taskGroups = new ArrayList<>();
        for (LocalDate deadline : taskGroupsByDeadline.keySet()) {
            List<Task> tasksForDeadline = taskGroupsByDeadline.get(deadline);
            taskGroups.add(new TaskGroup(deadline, tasksForDeadline.stream().map(Task::getName).collect(Collectors.toList())));
        }

        return taskGroups;
    }

