To enable secure messaging and file sharing within a Swift-based mobile application, you can use the MultipeerConnectivity framework provided by Apple. This framework enables communication between devices over Wi-Fi or Bluetooth, and it includes built-in encryption to ensure secure communication.
Here's a code snippet that demonstrates how to send a message and a file using MultipeerConnectivity:
```swift
import MultipeerConnectivity
class ViewController: UIViewController, MCSessionDelegate, MCBrowserViewControllerDelegate, UIImagePickerControllerDelegate, UINavigationControllerDelegate {
    var peerID: MCPeerID!
    var mcSession: MCSession!
    var mcAdvertiserAssistant: MCAdvertiserAssistant!
    var mcBrowser: MCBrowserViewController!

    override func viewDidLoad() {
        super.viewDidLoad()

        // Initialize peer ID and session
        peerID = MCPeerID(displayName: UIDevice.current.name)
        mcSession = MCSession(peer: peerID, securityIdentity: nil, encryptionPreference: .required)
        mcSession.delegate = self

        // Start advertising the session
        mcAdvertiserAssistant = MCAdvertiserAssistant(serviceType: "my-app", discoveryInfo: nil, session: mcSession)
        mcAdvertiserAssistant.start()

        // Show a browser to connect to other peers
        mcBrowser = MCBrowserViewController(serviceType: "my-app", session: mcSession)
        mcBrowser.delegate = self
    }

    // MARK: - MCSessionDelegate methods

    func session(_ session: MCSession, didReceive data: Data, fromPeer peerID: MCPeerID) {
        // Handle received data
    }

    func session(_ session: MCSession, peer peerID: MCPeerID, didChange state: MCSessionState) {
        // Handle peer connection state changes
    }

    func session(_ session: MCSession, didReceive stream: InputStream, withName streamName: String, fromPeer peerID: MCPeerID) {
        // Handle received streams
    }

    func session(_ session: MCSession, didStartReceivingResourceWithName resourceName: String, fromPeer peerID: MCPeerID, with progress: Progress) {
        // Handle receiving a file
    }

    func session(_ session: MCSession, didFinishReceivingResourceWithName resourceName: String, fromPeer peerID: MCPeerID, at localURL: URL?, withError error: Error?) {
        // Handle finished receiving a file
    }

    // MARK: - MCBrowserViewControllerDelegate methods

    func browserViewControllerDidFinish(_ browserViewController: MCBrowserViewController) {
        // Dismiss the browser
        dismiss(animated: true, completion: nil)
    }

    func browserViewControllerWasCancelled(_ browserViewController: MCBrowserViewController) {
        // Dismiss the browser
        dismiss(animated: true, completion: nil)
    }

    // MARK: - Message and file sending methods

    func sendMessage(message: String) {
        // Convert message to data
        let messageData = message.data(using: .utf8)!

        // Send message to all connected peers
        do {
            try mcSession.send(messageData, toPeers: mcSession.connectedPeers, with: .reliable)
        } catch {
            // Handle error sending message
        }
    }

    func sendFile(fileURL: URL) {
        // Send file to all connected peers
        do {
            try mcSession.sendResource(at: fileURL, withName: fileURL.lastPathComponent, toPeer: mcSession.connectedPeers.first!, withCompletionHandler: nil)
        } catch {
            // Handle error sending file
        }
    }
}
```
