foreach ($dom->getElementsByTagName('div') as $div) {
  if ($div->getAttribute('class') === 'product-info') {
    $name = $div->getElementsByTagName('h2')[0]->textContent;
    $price = $div->getElementsByTagName('span')[0]->textContent;
    $products[] = array('name' => $name, 'price' => $price);
