public class RandomWordGenerator {
    private static final String FILENAME = "words.json";
    private static final int WORD_LENGTH = 5;
    private static final Random RANDOM = new Random();
    public static void main(String[] args) {
        String word = generateRandomWord();
        String definition = getDefinition(word);
        System.out.println("Generated word: " + word);
        System.out.println("Definition: " + definition);
        addDefinition(word);
        String searchWord = "apple";
        String searchDefinition = searchDefinition(searchWord);
        System.out.println("Definition of " + searchWord + ": " + searchDefinition);
