```
#include <iostream>
using namespace std;
int findUnusualSuspect(int* sam_alibi, int* lisa_alibi, int* bill_alibi, int* paul_alibi) {
    int sum_sam = 0, sum_lisa = 0, sum_bill = 0, sum_paul = 0;
    for (int i = 0; i < 4; i++) {
        sum_sam += sam_alibi[i];
        sum_lisa += lisa_alibi[i];
        sum_bill += bill_alibi[i];
        sum_paul += paul_alibi[i];
    }
    if (sum_sam != sum_lisa && sum_sam != sum_bill && sum_sam != sum_paul) {
        return 1; // Sam is the Unusual Suspect
    }
    else if (sum_lisa != sum_sam && sum_lisa != sum_bill && sum_lisa != sum_paul) {
        return 2; // Lisa is the Unusual Suspect
    }
    else if (sum_bill != sum_sam && sum_bill != sum_lisa && sum_bill != sum_paul) {
        return 3; // Bill is the Unusual Suspect
    }
    else {
